const code = `const fs = require('fs');
const path = require('path');
const STORAGE_FILE = path.join(__dirname, '../tasks.json');
let tasks = [];
function loadTasks() {
  try {
    if (fs.existsSync(STORAGE_FILE)) {
      tasks = JSON.parse(fs.readFileSync(STORAGE_FILE, 'utf-8'));
    }
  } catch (err) {
    console.error('Failed to load tasks:', err);
    tasks = [];
  }
}
function saveTasks() {
  try {
    fs.writeFileSync(STORAGE_FILE, JSON.stringify(tasks, null, 2), 'utf-8');
  } catch (err) {
    console.error('Failed to save tasks:', err);
  }
}
function renderTasks() {
  const taskList = document.getElementById('taskList');
  const emptyMessage = document.getElementById('emptyMessage');
  taskList.innerHTML = '';
  if (tasks.length === 0) {
    emptyMessage.style.display = 'block';
    return;
  }
  emptyMessage.style.display = 'none';
  tasks.forEach((task, index) => {
    const li = document.createElement('li');
    li.className = 'task';
    li.innerHTML = \`
      <input type="checkbox" \${task.done ? 'checked' : ''} data-index="\${index}">
      <span class="task-text">\${escapeHtml(task.text)}</span>
      <button class="delete-btn" data-index="\${index}">삭제</button>
    \`;
    taskList.appendChild(li);
  });
  document.querySelectorAll('.task input[type="checkbox"]').forEach(checkbox => {
    checkbox.addEventListener('change', (e) => {
      const index = parseInt(e.target.dataset.index);
      tasks[index].done = e.target.checked;
      saveTasks();
      renderTasks();
    });
  });
  document.querySelectorAll('.delete-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const index = parseInt(e.target.dataset.index);
      tasks.splice(index, 1);
      saveTasks();
      renderTasks();
    });
  });
}
function addTask() {
  const input = document.getElementById('taskInput');
  const text = input.value.trim();
  if (text) {
    tasks.push({ text, done: false });
    saveTasks();
    renderTasks();
    input.value = '';
    input.focus();
  }
}
function escapeHtml(text) {
  const div = document.createElement('div');
  div.textContent = text;
  return div.innerHTML;
}
document.addEventListener('DOMContentLoaded', () => {
  loadTasks();
  renderTasks();
  const addBtn = document.getElementById('addBtn');
  const taskInput = document.getElementById('taskInput');
  addBtn.addEventListener('click', addTask);
  taskInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') addTask();
  });
});`;
fs.writeFileSync('./src/renderer.js', code);
console.log('Done');
